mapper.select:
SELECT S.ID AS "subjectId",UVA.content_id as "contentId", UVA.TYPE as "type", UVA.STAR_VALUE as "starValue", UVA.VALUE as "value" FROM GC_SUBJECT S LEFT JOIN GC_SUBJECT S0 ON S0.FID=S.ID LEFT JOIN GC_VIDEO V ON V.SUB_ID = S0.ID LEFT JOIN GC_USER_VIDEO_ACTION UVA ON UVA.content_id = V.ID
AND UVA.TYPE = #{type}
AND UVA.content_id IN
#{contentId}

SELECT UVA.sub_id AS "subjectId",COUNT(uva."user_id") as "subjectStarUsers", ROUND(AVG(UVA.STAR_VALUE)) as "subjectStarAvg" FROM GC_USER_VIDEO_ACTION UVA left join gc_subject s on s.id=UVA.sub_id WHERE UVA.type=4 and s.id in
#{id}
GROUP BY s.id, UVA.sub_id

select count(1) as videoLikeNum,content_id as contentId from gc_user_video_action where type =1 and content_id in
#{videoId}
group by content_id

select count(1) as videoLikeNum, content_id as contentId from gc_user_video_action where type = 1 and content_id in
#{contentId}
group by content_id
